long transnum(char s[]){              
    int i, comp = 0, alg;
    long num = 0;

    for(i=0; s[i] != '\0'; i++)
        comp++;

    for(i=0; s[i] != '\0'; i++){
        alg = s[i] - '0';
        num = num +  (alg * pot(comp));
        comp--;
    }
    return num;  
}

int pot(int e){
    int p = 1, b = 10;
    if(e == 0)
        return 1;
    else{
    while(e > 0){
        p = p*b;
        e--;
        }
    }
    return p;
}

